-- Official 2026 WNBA schedule: https://www.wnba.com/webview/news/2026-schedule-release
-- Existing legacy league and team IDs are shared, not duplicated. Toronto is Canadian.
-- Only pg_temp directory projection writes.
do $wnba$
declare
 lid constant uuid := '3e0e1b7c-b14c-4bf3-b0a7-a94b271ffed4';
 clubs uuid[] := array['0cb91473-6e77-446c-8088-2f67285f9948','18f29d86-aac8-4466-91a8-3c7ea5681174','1d4b3f2c-b046-402e-b244-6f96dc6cdb17','397a6d3a-b047-432d-942d-25a84cf562c4','4dd7249b-fd23-4392-90af-f7f6cd1353e8','63b5bede-a37e-4699-81a4-17ef29f6f9bb','90e9a8ee-da8a-4434-84d5-c43328a75ad0','b4d5020c-2cef-42b6-8f02-632daa028d3d','bd8e9670-b4ad-412e-b22c-59f183ff818b','c4fbab1d-7664-4d88-88ea-de9aac96db08','e98489aa-63c4-4c68-9317-9a8462d1ce1a','eb5cfa61-b802-408e-a6e3-1df6f1872755','f182c7ec-83e4-455b-9870-d1a23b1c33cb','fb6dd5a3-f927-4bfb-b5d9-f0840d4cd5ad','ff0e2bcf-b30b-42be-bcfe-88b8deee9252']::uuid[];
begin
 if not exists(select 1 from pg_temp.ld1_legacy_leagues where id=lid and name='Women''s National Basketball Association (WNBA)' and country='United States' and active)
 or exists(select 1 from pg_temp.ld1_leagues where id=lid and (name is distinct from 'Women''s National Basketball Association (WNBA)' or country is distinct from 'United States' or season is distinct from '2026' or basketball_type is distinct from 'womens' or active is not true))
 or exists(select 1 from pg_temp.ld1_leagues where id<>lid and basketball_type='womens' and (name ilike '%WNBA%' or name ilike '%Women%National Basketball Association%'))
 or (select count(*) from pg_temp.ld1_teams t join (values ('0cb91473-6e77-446c-8088-2f67285f9948'::uuid,'Phoenix Mercury','United States'),('18f29d86-aac8-4466-91a8-3c7ea5681174'::uuid,'Golden State Valkyries','United States'),('1d4b3f2c-b046-402e-b244-6f96dc6cdb17'::uuid,'Chicago Sky','United States'),('397a6d3a-b047-432d-942d-25a84cf562c4'::uuid,'Toronto Tempo','Canada'),('4dd7249b-fd23-4392-90af-f7f6cd1353e8'::uuid,'New York Liberty','United States'),('63b5bede-a37e-4699-81a4-17ef29f6f9bb'::uuid,'Seattle Storm','United States'),('90e9a8ee-da8a-4434-84d5-c43328a75ad0'::uuid,'Las Vegas Aces','United States'),('b4d5020c-2cef-42b6-8f02-632daa028d3d'::uuid,'Indiana Fever','United States'),('bd8e9670-b4ad-412e-b22c-59f183ff818b'::uuid,'Atlanta Dream','United States'),('c4fbab1d-7664-4d88-88ea-de9aac96db08'::uuid,'Minnesota Lynx','United States'),('e98489aa-63c4-4c68-9317-9a8462d1ce1a'::uuid,'Portland Fire','United States'),('eb5cfa61-b802-408e-a6e3-1df6f1872755'::uuid,'Connecticut Sun','United States'),('f182c7ec-83e4-455b-9870-d1a23b1c33cb'::uuid,'Washington Mystics','United States'),('fb6dd5a3-f927-4bfb-b5d9-f0840d4cd5ad'::uuid,'Dallas Wings','United States'),('ff0e2bcf-b30b-42be-bcfe-88b8deee9252'::uuid,'Los Angeles Sparks','United States')) e(id,name,country) on t.id=e.id and t.name=e.name and t.country=e.country join pg_temp.ld1_legacy_teams w on w.id=t.id and w.name=t.name and w.country=t.country where t.basketball_type='womens' and t.active and t.league_name='Women''s National Basketball Association (WNBA)' and (t.league_id is null or t.league_id=lid) and w.league_id=lid and w.active)<>15
 or exists(select 1 from pg_temp.ld1_teams where active and basketball_type='womens' and (league_name='Women''s National Basketball Association (WNBA)' or league_id=lid) and id<>all(clubs))
 or exists(select 1 from pg_temp.ld1_legacy_teams where active and league_id=lid and id<>all(clubs))
 or exists(select 1 from pg_temp.ld1_memberships where league_id=lid and season='2026' and (team_id<>all(clubs) or active is not true))
 then raise exception 'WNBA identity or legacy mirror changed; review required';end if;
 insert into pg_temp.ld1_leagues(id,name,country,season,basketball_type,active) values(lid,'Women''s National Basketball Association (WNBA)','United States','2026','womens',true) on conflict(id) do nothing;
 update pg_temp.ld1_teams set league_id=lid where id=any(clubs) and league_id is null;
 insert into pg_temp.ld1_memberships(id,team_id,league_id,season,active) select gen_random_uuid(),id,lid,'2026',true from unnest(clubs) id on conflict(team_id,league_id,season) do nothing;
 if (select count(*) from pg_temp.ld1_teams where league_id=lid and active)<>15 or (select count(*) from pg_temp.ld1_memberships where league_id=lid and season='2026' and active)<>15 or not exists(select 1 from pg_temp.ld1_teams where league_id=lid and name='Toronto Tempo' and country='Canada') then raise exception 'WNBA roster or country mismatch';end if;
end $wnba$;
